{"kind": "content", "icon": "🕳️", "head": "लालच एक गड्ढा है", "points": ["लालच कभी नहीं भरता", "जितना डालो, उतना ख़ाली", "इच्छाएँ बढ़ती जाती हैं", "संतोष ही इलाज है"], "say": "कवि ने लालच की तुलना एक गहरे गड्ढे से की है। आप उसमें जितना भी डालते जाइए, वह भरता ही नहीं। लालची आदमी के साथ भी यही होता है। एक लाख मिल जाए, तो उसे दस लाख चाहिए। दस लाख मिल जाए, तो करोड़ चाहिए। इच्छाएँ कभी ख़त्म नहीं होतीं, इसलिए उसका दिल हमेशा ख़ाली रहता है। इस बीमारी का एक ही इलाज है, संतोष। जो इंसान अपने पास की चीज़ों से ख़ुश रहना सीख लेता है, वही सच्चा अमीर कहलाता है।", "ext": 7},
{"kind": "content", "icon": "🎭", "head": "शीर्षक में विरोधाभास", "points": ["घर भरा हुआ, दिल ख़ाली", "धन बहुत, सुख कम", "विरोध से बात गहरी बनती है", "शीर्षक पूरी कविता की कुंजी"], "say": "कविता का शीर्षक है द एम्प्टी हार्ट, यानी ख़ाली दिल। ज़रा सोचिए, एक तरफ़ घर सोने से भरा है और दूसरी तरफ़ दिल ख़ाली। यही विरोधाभास कविता की जान है। कवि ने दो विपरीत बातों को साथ रखकर पाठक को चौंकाया है, ताकि वह रुककर सोचे। परीक्षा में अगर पूछा जाए कि शीर्षक कितना उपयुक्त है, तो लिखिए कि यह शीर्षक पूरी कविता का सार बता देता है। धन से तिजोरी भरती है, पर दिल तो प्रेम, संतोष और अपनेपन से भरता है।", "ext": 7},
{"kind": "content", "icon": "⚖️", "head": "संतोष बनाम लालच", "points": ["संतोषी कम में भी ख़ुश", "लालची ज़्यादा में भी दुखी", "संतोष से नींद अच्छी आती है", "लालच से रिश्ते बिगड़ते हैं"], "say": "अब संतोष और लालच की तुलना कीजिए। संतोषी आदमी के पास कम हो, तब भी वह ख़ुश रहता है और चैन की नींद सोता है। लालची आदमी के पास बहुत हो, तब भी वह दुखी रहता है और रात भर जागता है। संतोष से रिश्ते मज़बूत होते हैं, क्योंकि आदमी दूसरों के साथ बाँटकर चलता है। लालच से रिश्ते बिगड़ते हैं, क्योंकि आदमी हर चीज़ में अपना फ़ायदा देखता है। कहा भी गया है कि जब आवे संतोष धन, सब धन धूरि समान। यानी संतोष सबसे बड़ा धन है।", "ext": 7},
